insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('genre-cartoon-movie','apparel.vintage','genre','','เสื้อการ์ตูน/คอมิก/หนัง','',ARRAY['disney','mickey','looney','simpsons','marvel','spider-man','spiderman','star wars','pulp fiction','matrix','movie','การ์ตูน','หนัง']::text[],'["ลิขสิทธิ์ทางการมีบรรทัด © ของเจ้าของลิขสิทธิ์", "Marvel ยุค 90 เป็นที่ต้องการ: เสื้อ Spider-Man/Daredevil/Silver Surfer ปี 1997 เคยขายออนไลน์ได้ 220,000 บาท", "เสื้อโปรโมตหนังยุคแรก (Star Wars, Pulp Fiction, The Matrix) หลายรุ่นไม่ได้ผลิตขายทั่วไป นักสะสมตามหา"]'::jsonb,'["ลายการ์ตูนดังถูกพิมพ์ซ้ำเยอะ เช็คป้ายกับยุคของลายเสมอ"]'::jsonb,'ตัวที่ราคาสูงคือลายหายากและของเก่าจริง ลายทั่วไปราคาระดับกลาง','sourced','["https://www.benarnews.org/english/news/thai/secondhand-clothes-boom-deep-south-02142025113206.html", "https://esquire.co.th/2026/07/30/vintage-t-shirts-value-michael-b-jordan"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('genre-anime','apparel.vintage','genre','','เสื้ออนิเมะยุค 90 (Akira, Dragon Ball ฯลฯ)','',ARRAY['akira','dragon ball','dbz','ghost in the shell','anime','อนิเมะ','manga']::text[],'["Akira ถูกยกเป็นตัวท็อป ลายต้นฉบับปี 1988 มีรายงานราคาประมูลเกิน $3,000", "Dragon Ball Z ยุค 90 โดยเฉพาะลายพิมพ์รอบตัว (AOP), Ghost in the Shell", "ป้ายต้องเข้ากับยุคของลาย: ลาย Akira 1988 บนป้ายยุค 2010 = พิมพ์ใหม่", "ตะเข็บเดี่ยว, สกรีนซึมเนื้อผ้า, © พิมพ์ลงเนื้อผ้า ไม่ลอยบนผิว"]'::jsonb,'["ซีดด้วยน้ำยาฟอกขาวเลียนแบบความเก่า", "ลายพิมพ์ดิจิทัล/รีดร้อนที่ผิวเป็นพลาสติก"]'::jsonb,'ตัวเลขราคามาจากร้านขาย ยังไม่มีแหล่งอื่นยืนยัน ใช้เป็นแนวทางเท่านั้น','general','["https://www.yiume.com/es/pages/faq-why-vintage-anime-shirts-expensive-2026"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('band-value','apparel.vintage','genre','','เสื้อวงที่ราคาสูง (ข้อมูลขายจริง)','',ARRAY['nirvana','grateful dead','bjork','björk','soundgarden','metallica','red hot chili peppers','rhcp','guns n roses','guns n'' roses','green day','pearl jam','earth wind','oasis','pushead']::text[],'["ผลศึกษาราคาขายต่อ (ธ.ค. 2023–ก.ย. 2024): Grateful Dead \"Panther\" สูงสุด $2,750, Nirvana In Utero แขนยาว $2,000, Björk Post (1995), Soundgarden Louder Than Love (1989), Metallica Load (1996), Nirvana Sliver tour (1992)", "วงที่ราคาเฉลี่ยต่อตัวสูง: Nirvana, Red Hot Chili Peppers, Earth Wind & Fire, Guns N'' Roses, Green Day, Paul McCartney, Pearl Jam", "ยุคที่ราคาดีที่สุด: ปลายยุค 80 ถึงกลางยุค 90 แนวร็อกราคาเฉลี่ยสูงกว่าป๊อปและแร็ป", "Grateful Dead ลาย Dancing Bears/Skeleton และ Metallica ลายของ Pushead เป็นที่ตามหา", "Oasis ยุค 90 ความต้องการเพิ่มขึ้นหลังประกาศรียูเนียนปี 2025"]'::jsonb,'["ราคาประเมินกับราคาซื้อขายจริงต่างกันได้มาก (เช่น เสื้อ Nirvana staff ปี 1991 ที่มีข่าวประเมิน 1.35 ล้านบาท แต่เจ้าของซื้อมาหลักหมื่น)", "วงดังที่สุดคือวงที่มีของพิมพ์ใหม่มากที่สุด"]'::jsonb,'เสื้อทัวร์ทางการ/ลายอัลบั้มเฉพาะ และเสื้อทีมงานที่ผลิตน้อย ราคาสูงสุด','sourced','["https://loudwire.com/study-bands-most-valuable-vintage-t-shirts/", "https://esquire.co.th/2026/07/30/vintage-t-shirts-value-michael-b-jordan", "https://marketeeronline.co/archives/429691"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('market-thai-bale','apparel.vintage','market','','ตลาดเสื้อมือสองกระสอบในไทย','',ARRAY['กระสอบ','bale','มือสอง','โรงเกลือ','ยะลา','ปัตตานี']::text[],'["เสื้อมือสองส่วนใหญ่มาจากสหรัฐฯ ส่งเรือไปมาเลเซียแล้วเข้าไทย", "ตัวอย่างจากภาคใต้: กระสอบละราว 1,000 บาท มีเสื้อยืด 200–220 ตัว หรือแจ็คเก็ต/กางเกง 150–180 ตัว", "ตลาดที่มีข่าว: ตลาดมะพร้าว (ยะลา), รูสะมิแล และยะหริ่ง (ปัตตานี)", "ของที่ขายได้ราคา: เสื้อยืดผลิตในสหรัฐฯ ผ้าบาง (นักสะสมญี่ปุ่นชอบ), เสื้อวงทั้งทางการและ bootleg, เสื้อทหารยุคสงคราม, ชุดทำงาน, ยีนส์, เสื้อกีฬา, เสื้อฮาวาย", "ตัวอย่าง: เสื้อยุค 70 ซื้อ 80 บาท ขายได้ 22,000 บาท"]'::jsonb,'[]'::jsonb,'กำไรมาจากการรู้ว่าตัวไหนมีค่า ใช้โหมดสแกนรัวคัดกอง','sourced','["https://www.benarnews.org/english/news/thai/secondhand-clothes-boom-deep-south-02142025113206.html"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('trend-now','apparel.vintage','trend','','กระแสตอนนี้ (อัปเดต พ.ย. 2026)','',ARRAY['trend','กระแส','blokecore','oasis','world cup']::text[],'["เสื้อกราฟิก/วินเทจกลับมาได้รับความสนใจในช่วง 2–3 ปีที่ผ่านมา เสื้อวงและเสื้อหนังนิยมสูง", "เสื้อบอลย้อนยุคมาแรงจากกระแส blokecore และฟุตบอลโลก 2026", "Oasis ยุค 90 ความต้องการเพิ่มหลังรียูเนียน", "เสื้ออนิเมะยุค 90 คนรุ่นใหม่สนใจ"]'::jsonb,'["กระแสเปลี่ยนเร็ว ควรอัปเดตหัวข้อนี้ทุก 2–3 เดือน"]'::jsonb,'','sourced','["https://esquire.co.th/2026/07/30/vintage-t-shirts-value-michael-b-jordan", "https://www.outlookindia.com/sports/football/fifa-world-cup-2026-hottest-jerseys-blokecore-retro-shirts-fashion-trends", "https://marketeeronline.co/archives/429691"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('levis-tab','apparel.denim','brand','','Levi''s: แท็บแดง (Big E / small e)','',ARRAY['levi''s','levis','levi','big e','red tab','แท็บแดง','บิ๊กอี']::text[],'["Big E (LEVI''S ตัว E ใหญ่) = ก่อนปี 1971", "small e (Levi''s ตัว e เล็ก) = ตั้งแต่ 1971", "แท็บพิมพ์ด้านเดียว = รุ่นเก่ามาก (ราวก่อนกลางยุค 50)", "ราว 10% ของการผลิตใช้แท็บเปล่า แท็บเปล่าจึงไม่ได้บอกยุค", "small e บางรุ่นก็หายากและมีราคา"]'::jsonb,'["Big E กลับมาใช้อีกตั้งแต่ 2018 บนสินค้าพรีเมียม", "LVC (Levi''s Vintage Clothing) และของปลอมอาจมีทั้ง Big E และป้ายวิธีซัก = ต้องดูป้ายวิธีซักและรายละเอียดอื่นประกอบ"]'::jsonb,'Big E ราคาสูงกว่ามาก','sourced','["https://www.thecollectorscompanion.co.uk/features/vintage-clothing/dating-levis/", "https://www.ropedye.com/2013/05/guide-how-to-date-levis-501-jeans/", "https://selvedgestory.pages.dev/en/guide/vintage-denim-authentication-guide/"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('levis-construction','apparel.denim','rule','','Levi''s: หมุด ตะเข็บ ริม ป้ายหลัง','',ARRAY['levi''s','levis','501','selvedge','redline','ริมแดง','hidden rivet']::text[],'["หมุดซ่อนในกระเป๋าหลัง 1937–1966 จากนั้นเปลี่ยนเป็นบาร์แทค", "ป้ายหนัง Two Horse จนถึงราว 1955 จากนั้นเป็นป้ายกระดาษ (Jacron)", "ผ้าริม (selvedge/ริมแดง) ด้านในตะเข็บข้างขา = ราวก่อนกลางยุค 80", "ตะเข็บด้านนอกขาแบบโพ้งสีส้มราว 1981, โพ้งสีขาวราว 1985", "ตะเข็บด้านบนกระเป๋าหลังแบบเดี่ยว (lock stitch) ราวก่อน 1976 จากนั้นเป็นแบบโซ่", "หลังเอวรัด (cinch back) เลิกราว 1947"]'::jsonb,'["ซีดสม่ำเสมอผิดธรรมชาติหรือฟอกดูถูก = ระวัง", "ของ repro ญี่ปุ่นทำรายละเอียดได้เหมือนมาก ต้องดูหลายจุดประกอบ"]'::jsonb,'','sourced','["https://www.thecollectorscompanion.co.uk/features/vintage-clothing/dating-levis/", "https://www.ropedye.com/2013/05/guide-how-to-date-levis-501-jeans/", "https://selvedgestory.pages.dev/en/guide/vintage-denim-authentication-guide/"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('levis-care','apparel.denim','rule','','Levi''s: อ่านป้ายวิธีซักและรหัสวันผลิต','',ARRAY['levi''s','levis','care tag','care label','ป้ายวิธีซัก']::text[],'["ไม่มีป้ายวิธีซักเลย = ก่อนราว 1971", "ราว 1968–1972: วิธีซักพิมพ์ในผ้ากระเป๋า", "1973–1983: ป้ายกระดาษเล็กข้างตะเข็บซ้าย มีวงกลมสีบอกรหัส", "ราว 1984 เป็นต้นไป: รหัส 3 หลัก เช่น 127 = ธันวาคม 1987", "1993 เป็นต้นไป: รหัส 4 หลัก เช่น 1295 = ธันวาคม 1995", "ป้ายรูป batwing ตั้งแต่ 1986/1987, คำว่า \"Care on Reverse\" = ก่อนราว 1992", "Made in USA สิ้นสุดราวปี 2003"]'::jsonb,'["ป้ายบอกปีล่าสุดแต่ดีไซน์อ้างว่าเก่า = รุ่น repro/LVC"]'::jsonb,'','sourced','["https://levis-vintage-id.vercel.app/en/articles/article-care-label", "https://www.thecollectorscompanion.co.uk/features/vintage-clothing/dating-levis/"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('levis-jackets','apparel.denim','brand','','Levi''s: แจ็คเก็ตยีนส์ Type I / II / III','',ARRAY['jacket','trucker','506xx','507xx','557','70505','แจ็คเก็ต','type i','type ii','type iii']::text[],'["Type I (506XX): ก่อนยุค 40 กระเป๋าหน้าเดียวมีหมุดที่มุม หลังมีหัวเข็มขัดรัด (หายากสุด)", "Type II (507XX): ปลายยุค 40–60 กระเป๋าอกสองข้างมีฝาติดกระดุม ใช้บาร์แทคแทนหมุด", "Type III (557XX): 1962 ฝากระเป๋าแหลม (ทรง Trucker)", "ก่อน 1971: ตะเข็บแถวเดียวที่รังกระดุมล่าง; ตั้งแต่ 1971: ตะเข็บสองแถว + small e", "กลางยุค 80 ขึ้นไป: 4 กระเป๋า (อก 2 + ล้วงข้าง 2) นักสะสมสนใจน้อยกว่า"]'::jsonb,'[]'::jsonb,'ยิ่งเก่า (Big E, 2 กระเป๋า) ยิ่งแพง','sourced','["https://bragvintage.com/levis-denim-jacket-guide"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('lee','apparel.denim','brand','','Lee 101 / 101Z','',ARRAY['lee','101z','101j','storm rider','lazy s']::text[],'["ผ้า Left-Hand Twill (ลายทแยงกลับด้านกับ Levi''s)", "ตะเข็บกระเป๋าหลังรูป Lazy S (ปรับดีไซน์ราว 1944–1946)", "101Z ซิปหน้าเริ่มราว 1926–1927", "ป้ายเปลี่ยนจากหนังเป็นกระดาษใส"]'::jsonb,'[]'::jsonb,'','sourced','["https://selvedgestory.pages.dev/en/guide/vintage-denim-authentication-guide/"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('wrangler','apparel.denim','brand','','Wrangler 13MWZ','',ARRAY['wrangler','13mwz','blue bell','11mwz']::text[],'["13MWZ เปิดตัว 1947", "ผ้าทวิลธรรมดา 1947–1963, ผ้า Broken Twill ตั้งแต่ 1964", "หมุดซ่อน ตะเข็บรูป W นูนที่กระเป๋าหลัง ซิปหน้า"]'::jsonb,'[]'::jsonb,'','sourced','["https://selvedgestory.pages.dev/en/guide/vintage-denim-authentication-guide/"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('carhartt','apparel.denim','brand','','Carhartt','',ARRAY['carhartt','detroit jacket','j01','j97','chore coat','double knee']::text[],'["รหัสวันที่ในป้ายวิธีซัก อ่านเป็นเดือน-ปี เช่น 0698 = มิถุนายน 1998, ต้นยุค 90 อาจไม่มีศูนย์นำหน้า เช่น 591 = พฤษภาคม 1991", "ป้าย Union + Made in USA = ยุคก่อนย้ายฐานผลิต", "J01 Detroit: ผ้าดั๊กแข็ง 12oz ไซซ์เป็นตัวเลข (38–44) ปกลูกฟูก", "J97 Detroit: ปลายยุค 90 ไซซ์ตัวอักษร ผ้านุ่มกว่า"]'::jsonb,'["ซิปไม่มียี่ห้อเบาๆ (ของเก่ามักเป็น YKK หนัก หรือ Talon ทองเหลือง)", "ปักโลโก้ใหญ่หรือเบี้ยว", "ซับในฟลีซเทาสังเคราะห์ (ของเก่ามักเป็นซับผ้าห่มลายสก็อต)", "ทำเก่าด้วยเคมี"]'::jsonb,'Detroit Jacket และ Made in USA เป็นที่ต้องการ','sourced','["https://nostos.pages.dev/guides/identifying-vintage-carhartt-and-workwear"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('denim-general','apparel.denim','rule','','ยีนส์วินเทจ: ดูผ้าและการซีด','',ARRAY['denim','jeans','ยีนส์','rope dye']::text[],'["ยีนส์เก่าส่วนใหญ่ย้อมแบบ rope dye ซีดเป็นเส้นแนวตั้ง มีรอยรังผึ้งหลังเข่าและหนวดแมว", "ผ้ายีนส์วินเทจมักหนาราว 13–15oz"]'::jsonb,'["ซีดสม่ำเสมอผิดธรรมชาติ", "อย่าเชื่อป้าย \"Made in [ปี]\" หรือคำบรรยายของผู้ขายโดยไม่ตรวจเอง", "อย่าใช้ Big E อย่างเดียวตัดสิน"]'::jsonb,'','sourced','["https://selvedgestory.pages.dev/en/guide/vintage-denim-authentication-guide/"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('fb-rule-check','apparel.football','rule','','เสื้อบอล: เช็คของแท้พื้นฐาน','',ARRAY['football','soccer','jersey','kit','เสื้อบอล','เสื้อฟุตบอล','product code']::text[],'["หารหัสสินค้าบนป้ายด้านใน แล้วค้นใน Google ต้องขึ้นเสื้อตัวเดียวกันเป๊ะ (ทีม ปี เหย้า/เยือน)", "ผู้ขายไม่ยอมโชว์ป้าย = สัญญาณเตือน, ป้ายถูกตัดออก = ซื้อเสี่ยงเอง", "เทียบสี ความคมของลาย และตำแหน่งดีไซน์กับรูปจากร้านทางการ"]'::jsonb,'["ป้ายเสื้อเก่ามีรอยปากกา/ดินสอเขียน", "เสื้อออกใหม่ลด 50% หรือของหายากราคาถูกผิดปกติ", "เสื้อก่อนปี 2000 มีครบทุกไซซ์ XS–XXL", "ประกาศใช้คำว่า \"replica\" หรือ \"retro\" (อาจเป็นงานทำใหม่หรือของปลอม)"]'::jsonb,'','sourced','["https://footballshirtcollective.com/blogs/collectors-club/spot-a-fake-shirt"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('fb-thai-grade','apparel.football','rule','','คำว่า "เกรดเอ / เกรดแฟนบอล / เกรดนักเตะ" ในไทย','',ARRAY['เกรดเอ','เกรด a','aaa','เกรดไทย','งานไทย','เกรดนักเตะ','เกรดแฟนบอล']::text[],'["ในไทยมีร้านขายเสื้อบอลที่ระบุว่า \"เกรดเอ/เกรดแฟนบอล/เกรดนักเตะ/เกรดพรีเมียม\" แยกจากของลิขสิทธิ์", "ของลิขสิทธิ์จริงก็มีรุ่นนักเตะ (Player/Authentic) กับรุ่นแฟน (Replica) แต่ต้องเช็ครหัสสินค้าได้"]'::jsonb,'["ผู้ขายเรียกว่า \"เกรด...\" แทนการบอกว่าลิขสิทธิ์แท้ = ให้ถือว่าไม่ใช่ของลิขสิทธิ์ อย่าซื้อในราคาของแท้ และอย่าขายต่อว่าเป็นของแท้"]'::jsonb,'','general','["https://www.welovefootballshop.com/product/tag/%E0%B9%80%E0%B8%AA%E0%B8%B7%E0%B9%89%E0%B8%AD%E0%B8%9F%E0%B8%B8%E0%B8%95%E0%B8%9A%E0%B8%AD%E0%B8%A5%E0%B8%AB%E0%B8%A5%E0%B8%B1%E0%B8%87%E0%B8%AA%E0%B8%99%E0%B8%B2%E0%B8%A1%E0%B8%A8%E0%B8%B8%E0%B8%A0?tskp=13"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('fb-player-fan','apparel.football','rule','','รุ่นนักเตะ (Player/Authentic) vs รุ่นแฟน (Replica)','',ARRAY['player issue','player version','authentic','replica','fan version','vaporknit','dri-fit adv','heat.rdy','aeroready','รุ่นนักเตะ','รุ่นแฟน']::text[],'["รุ่นนักเตะ: ทรงเข้ารูป ผ้าบางเบาระบายอากาศ โลโก้/ตราแบบรีดร้อน ใช้ Nike Dri-FIT ADV หรือ adidas HEAT.RDY", "รุ่นแฟน: ทรงปกติ ผ้าหนากว่า โลโก้/ตราแบบปัก ใช้ Nike Dri-FIT หรือ adidas AEROREADY", "ทั้งสองรุ่นเป็นของลิขสิทธิ์ คำว่า \"authentic\" หมายถึงรุ่นนักเตะ", "ราคาป้ายยุโรป: รุ่นนักเตะราว €140–160, รุ่นแฟนราว €90–110", "เสื้อยุคเก่า รุ่นนักเตะกับรุ่นแฟนแยกกันชัดเจนแค่ราว 10 ปีหลัง"]'::jsonb,'[]'::jsonb,'','sourced','["https://first11shirts.com/blogs/informative/player-vs-fan-version-football-shirts-what-s-the-difference", "https://themomentum.co/feature-football-jersey/"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('fb-nike','apparel.football','brand','','Nike: เช็คเสื้อบอล','',ARRAY['nike','swoosh']::text[],'["รหัสสินค้า: ป้ายเล็กด้านในใกล้ชายเสื้อ รูปแบบ ตัวเลข 6 หลัก-3 หลัก (เช่น 123456-789) ค้นแล้วต้องขึ้นเสื้อตัวนั้นเป๊ะ", "Jock tag (ป้ายด้านหน้ามุมล่าง) มีรหัสยาวที่ไม่ซ้ำกันในแต่ละตัว", "เสื้อรุ่นใหม่มีป้ายที่ปลายแขน", "ขอบ swoosh คม"]'::jsonb,'["รหัสสินค้าขึ้นเป็นเสื้ออีกตัว (เช่น ชุดเหย้าแทนชุดเยือน)", "ไม่มีป้ายรหัสสินค้า", "รหัส jock tag ซ้ำกับเสื้อหลายตัว", "ปลาย swoosh ลากยาว งานปักเละ", "ด้านในหลัง swoosh/ตรามีวัสดุรองเกินมาก (สัญญาณคลาสสิก)", "ป้ายคอบนเสื้อรุ่นใหม่ (ไม่ได้ปลอมเสมอ แต่ต้องเช็คเพิ่ม)", "France 2016 ชุดเยือน เป็นรหัสที่ของปลอมใช้บ่อย"]'::jsonb,'','sourced','["https://footballshirtcollective.com/blogs/collectors-club/spot-fake-nike"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('fb-adidas','apparel.football','brand','','adidas: เช็คเสื้อบอล','',ARRAY['adidas','three stripes','trefoil']::text[],'["รหัสสินค้าที่ป้ายคอด้านใน: ตัวอักษร 2 ตัว + ตัวเลข 4 ตัว (เช่น DP2644) ค้นแล้วต้องตรงเสื้อ", "ป้ายคอของแท้มีตัวย่อชื่อสโมสร/ประเทศ", "โลโก้: ตัวหนังสือแตะขอบล่างของแถบ ระยะตัวอักษรสม่ำเสมอ แถบตรง", "jock tag มักอยู่มุมล่างด้านหน้า ไม่มีก็ไม่ได้แปลว่าปลอม (รุ่นแฟนบางรุ่นไม่มี)"]'::jsonb,'["ป้ายคอเขียนกว้างๆ ว่า \"ADIDAS JSY\"", "ป้ายคอติดกลับหัว", "ด้ายลากระหว่างตัวอักษร ฟอนต์บางเกิน แถบเบี้ยว ผ้าย่นรอบโลโก้", "ของหายากราคาถูก หรือมีครบทุกไซซ์"]'::jsonb,'','sourced','["https://footballshirtcollective.com/blogs/collectors-club/spot-fake-adidas"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('fb-umbro','apparel.football','brand','','Umbro ยุค 90','',ARRAY['umbro']::text[],'["ป้ายคอสีน้ำเงิน ตัวอักษร UMBRO มีจุดชัด", "บางตัวมีป้ายขาวบอกไซซ์/วิธีซักใต้ป้ายน้ำเงิน (ต้นยุค 90 มักไม่มี ปลายยุค 90 เกือบทุกตัวมี)", "ป้ายคอสีขาวตัวอักษรน้ำเงิน พบบ่อยในเสื้อ Celtic", "ช่วง 1998–2000 เปลี่ยนแบบป้าย อาจเจอทั้งสองแบบในเสื้อลายเดียวกัน"]'::jsonb,'["ไม่มีจุดในตัวอักษร UMBRO", "ป้ายแบนเรียบ เย็บน้อยกว่า (แต่ป้ายยุค 90 เย็บไม่สวยก็เป็นของแท้ได้)"]'::jsonb,'','sourced','["https://casualfootballshirts.co.uk/pages/1990s-umbro-shirts-authenticity-checks"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('fb-kappa','apparel.football','brand','','Kappa','',ARRAY['kappa','omini','kombat']::text[],'["รุ่นใหม่: ป้ายด้านในมีหมายเลข/QR ตรวจที่ BasicLabels.net", "ยุค 90: ป้ายหลักด้านในมีจุด 6 จุดเรียงสองแนวทแยง สม่ำเสมอ", "ของแท้มักมีป้ายด้านในมากกว่าของปลอม", "Barcelona 1992–95 ชุดเหย้า: ด้านหน้าไม่มีโลโก้ Kappa ดูป้าย \"Barça F.C.B.\" และ \"Sports Kappa S.A.\" ด้านใน"]'::jsonb,'["หมายเลขตรวจไม่เจอหรือขึ้นเสื้อตัวอื่น", "จุดบนป้ายกระจายไม่เท่ากัน", "ตัวอักษร Kappa ป่อง", "รูปคนสองคนใน Omini ผิดทรง", "ป้าย KOMBAT แบบตัวอักษรเจาะทะลุ"]'::jsonb,'เสื้อ Kappa ยุค 90 ถูกปลอมเยอะมาก','sourced','["https://footballshirtcollective.com/blogs/collectors-club/spot-fake-kappa"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('fb-demand-thai','apparel.football','genre','','เสื้อบอลวินเทจที่คนไทยตามหา','',ARRAY['manchester united','man utd','แมนยู','everton','ac milan','milan','man city','แมนซิตี้','real madrid','southampton','liverpool','ลิเวอร์พูล','sharp','batistuta','shevchenko','totti','gerrard','beckham','england 1990']::text[],'["นักเตะยุค 90–2000 ที่นิยม: Batistuta, Shevchenko, Totti, Gerrard, Le Tissier", "Everton และแมนยูยุคสปอนเซอร์ Sharp", "AC Milan ชุดเหย้าครบรอบ 100 ปี, แมนซิตี้ชุดเยือน 1993–94 (แฟน Oasis ตาม), เรอัลมาดริดยุค Beckham, อังกฤษฟุตบอลโลก 1990", "หายาก: Southampton 1991–93, แมนยูชุดเยือน 1970", "ราคาที่บทความระบุ: ส่วนใหญ่หลักร้อยถึงหลักพัน, AC Milan 100 ปี 8,000–10,000 บาท, แมนซิตี้เยือน 93–94 ตั้งแต่ 15,000 บาท, แมนยูเยือน 1970 หลักหมื่นขึ้นไป", "ร้านเฉพาะทาง: TJ Football Shop จตุจักร (อาคารตึกแดง)"]'::jsonb,'["ความร้อนทำให้เบอร์/ชื่อที่พิมพ์ละลาย เก็บในถุง ไม่ตากแดด", "การติดอาร์มแขนไม่ดีทำให้เสื้อเสียหาย"]'::jsonb,'ยุค 70–80 หายากที่สุด ทีม/ฤดูกาลที่ผูกกับนักเตะหรือเหตุการณ์ดังราคาดี ราคาในบทความอาจเปลี่ยนแล้ว','sourced','["https://themomentum.co/feature-football-jersey/"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('fb-demand-global','apparel.football','trend','','เสื้อบอลย้อนยุคที่ฮิต (กระแส blokecore + ฟุตบอลโลก 2026)','',ARRAY['germany','nigeria','brazil','argentina','england','mexico','france','croatia','japan','canada','norway','world cup','blokecore','ทีมชาติ']::text[],'["ย้อนยุคที่ฮิต: เยอรมนี Italia 90, ไนจีเรีย 1994, บราซิล 2002, อาร์เจนตินา 1986, อังกฤษ Euro 96, เม็กซิโก 1998, ฝรั่งเศส 1998, โครเอเชีย 1998", "ชุดฟุตบอลโลก 2026 ที่ถูกพูดถึง: เยอรมนีเหย้า, เม็กซิโกเหย้า, ญี่ปุ่นเยือน, แคนาดาเยือนสีดำ, นอร์เวย์, อาร์เจนตินา", "กระแส blokecore ใส่เสื้อบอลคู่กับยีนส์ทรงหลวม"]'::jsonb,'["ชุดที่ฮิตคือชุดที่ถูกทำซ้ำ (retro remake) และปลอมมากที่สุด เช็ครหัสสินค้าเสมอ"]'::jsonb,'','sourced','["https://www.outlookindia.com/sports/football/fifa-world-cup-2026-hottest-jerseys-blokecore-retro-shirts-fashion-trends"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('fb-thailand','apparel.football','genre','','เสื้อทีมชาติไทย','',ARRAY['thailand','ทีมชาติไทย','ช้างศึก','ชบาแก้ว','grand sport','แกรนด์สปอร์ต','warrix','วอริกซ์']::text[],'["ผู้ผลิตที่ผ่านมา: Grand Sport และปัจจุบัน Warrix มีทั้งเกรดนักเตะและเกรดแฟน", "ที่นักสะสมสนใจ: Grand Sport ลาย \"ศักดิ์ศรีปฐพีไทย\" และเสื้อครบรอบ 100 ปี (2016–17) ที่บทความบอกว่าหายากแล้ว, รุ่น Limited Edition", "ราคาป้าย Warrix ฤดูกาล 2023/24: Player 2,490 บาท, Replica 890 บาท, เสื้อเชียร์ 399 บาท"]'::jsonb,'["เสื้อเชียร์ราคาถูกไม่ใช่เสื้อแข่ง อย่าตีราคาเท่ารุ่น Player"]'::jsonb,'','sourced','["https://www.ktc.co.th/article/lifestyle/sport/thailand-national-team-kits", "https://www.bangkokbiznews.com/lifestyle/1085512", "https://www.classicfootballshirts.co.uk/2016-17-thailand-100th-anniversary-shirt-xl-this16365185.html"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('shoe-nike-sku','shoes.brand','rule','Nike','Nike/Jordan: เช็ครหัสสินค้า (style code)','',ARRAY['nike','jordan','air max','air force','dunk','style code','sku']::text[],'["ป้ายในลิ้นมีรหัส 6 ตัว-3 ตัว เช่น CW2288-111 (ตัวหลังคือรหัสสี)", "รหัสในลิ้นต้องตรงกับป้ายกล่องทุกตัว", "เอารหัสไปค้น Google ต้องขึ้นรุ่นและสีเดียวกับรองเท้าที่ถือ", "ช่วงวันผลิตบนป้ายต้องสมเหตุสมผลกับปีที่รุ่นนั้นวางขาย"]'::jsonb,'["รหัสค้นแล้วขึ้นรุ่นหรือสีอื่น", "ไม่มีรหัส หรือรหัสในลิ้นกับกล่องไม่ตรงกัน", "ราคาต่ำกว่าป้ายมาก (ของปลอมเกรดดีมักตั้ง 40–60% ของราคาป้าย)"]'::jsonb,'','sourced','["https://urbanstylefootwear.com/check-nike-authenticity/"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('shoe-build','shoes.brand','rule','','รองเท้าแบรนด์: ดูงานประกอบ','',ARRAY['sneaker','รองเท้า','glue','stitching']::text[],'["ตะเข็บถี่ เท่ากัน เส้นตรง", "แนวกาวระหว่างตัวรองเท้ากับพื้นเรียบ ไม่ล้น", "บีบส้นด้านหลัง (heel counter) ต้องแข็ง ไม่ยุบแบน", "กดโฟมพื้นต้องเด้งกลับทันที", "กลิ่นหนัง/ยาง/กาวโรงงานปกติ"]'::jsonb,'["กาวล้นเป็นก้อนหรือมีช่องว่างไม่มีกาว", "กลิ่นสารเคมีแรงแบบทินเนอร์", "ฝีเข็มห่าง ด้ายหลุดลุ่ย"]'::jsonb,'','sourced','["https://urbanstylefootwear.com/check-nike-authenticity/"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('shoe-dunk-j1','shoes.brand','brand','Nike','Nike Dunk / Air Jordan 1: จุดที่ของปลอมพลาดบ่อย','',ARRAY['dunk','jordan 1','aj1','panda']::text[],'["ทรงส้นเท้าด้านหลังเป็นทรงนาฬิกาทราย (เว้าตรงกลาง)", "โลโก้ Swoosh ปลายแหลมคม วางตำแหน่งตามรุ่น", "ปักโลโก้ที่ลิ้นแน่น ตัวอักษรไม่ติดกัน", "ป้ายในลิ้นพิมพ์คม ฟอนต์ไม่หนา"]'::jsonb,'["ส้นตรงทื่อไม่มีเว้า", "หนังแข็งมันวาวแบบพลาสติก", "รู้กันว่ารุ่น Panda ปลอมเยอะที่สุดในตลาด ต้องเช็คละเอียด"]'::jsonb,'Dunk Panda มือสองสภาพดีขายง่ายแต่ราคาไม่สูง; รุ่นคอลแลบ/สีหายากราคาดีกว่ามาก','sourced','["https://legitcheck.app/guides/nike/dunk/real-vs-fake-dunk-universal/", "https://madkicks.com/blog/how-to-spot-fake-jordan-1s-real-vs-fake-guide"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('shoe-converse-usa','shoes.brand','brand','Converse','Converse Chuck Taylor ผลิตในอเมริกา (วินเทจ)','ก่อนราวปี 2001',ARRAY['converse','chuck taylor','all star','made in usa']::text[],'["ป้ายส้นวงกลมสีน้ำเงิน: ดาวใหญ่สีขาว + \"Made in U.S.A.\" ล่างซ้าย ลายเซ็น Chuck Taylor ล่างขวา", "ด้านในลิ้นมีป้ายชื่อ + ช่อง \"Players Name\"", "หัวยางเล็กกว่ารุ่นปัจจุบัน รูร้อยเชือกห่างกว่า", "เส้นยางขอบพื้นหนากว่าเล็กน้อย"]'::jsonb,'["รุ่นใหม่ป้ายส้นมีเครื่องหมาย ® และตัวอักษร ALL STAR ใหญ่", "Chuck 70 (ผลิตใหม่) หน้าตาคล้ายวินเทจแต่ไม่ใช่ของเก่า"]'::jsonb,'คู่ Made in USA สภาพดีราคาสูงกว่า Chuck 70 หลายเท่า; ไซส์ใหญ่และสีหายากขายง่าย','sourced','["https://chucksconnection.com/vintage.html"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('shoe-nb-made','shoes.brand','brand','New Balance','New Balance Made in USA / Made in UK','',ARRAY['new balance','nb','990','992','993','991','1500','made in usa','made in uk']::text[],'["รุ่นผลิตในอเมริกา/อังกฤษเขียนประเทศชัดบนลิ้นหรือป้ายใน (MADE IN USA / MADE IN ENGLAND)", "ราคาป้ายสูงกว่ารุ่นผลิตในเอเชียมาก", "New Balance ระบุว่ารุ่น \"Made in USA\" มีส่วนผลิตในอเมริกาอย่างน้อย 70% ของมูลค่า"]'::jsonb,'["ผู้ขายอ้าง Made in USA แต่ป้ายเขียนประเทศอื่น"]'::jsonb,'99x ซีรีส์มือสองมีตลาดในไทย ราคาขึ้นกับไซส์และสภาพพื้น','sourced','["https://truthinadvertising.org/evidence/newbalance-origin-information/"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('shoe-onitsuka','shoes.brand','brand','Onitsuka Tiger','Onitsuka Tiger / ASICS','',ARRAY['onitsuka','mexico 66','asics','tiger']::text[],'["ป้ายในมีรหัสรุ่นตรงกับกล่อง (เช่น 1183A201)", "แถบลายข้าง (Tiger stripes) เย็บเรียบ ปลายเสมอกัน", "Mexico 66 รุ่น NIPPON MADE ผลิตญี่ปุ่น ราคาสูงกว่ารุ่นปกติ"]'::jsonb,'["ของปลอมเยอะมากในไทย ราคาถูกผิดปกติ", "ฟอนต์บนลิ้นหนา/เบี้ยว"]'::jsonb,'','general','[]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('shoe-condition','shoes.brand','rule','','ตีราคารองเท้ามือสองตามสภาพ','',ARRAY['รองเท้ามือสอง','ส้นสึก','sole','yellowing','crumbling']::text[],'["ดูพื้นสึกด้านส้นและหัวแม่เท้า", "พื้นยางเหลือง (yellowing) ขัดได้บางส่วน", "รองเท้าเก่ามากพื้นโฟม PU อาจกรอบแตกเมื่อใส่ (crumbling)", "มีกล่องเดิม + ป้ายครบ เพิ่มราคาได้ชัด", "ไซส์ยอดนิยมผู้ชาย US 8.5–10 ขายเร็วสุด"]'::jsonb,'["พื้นแยก/กาวหลุด ต้องส่งซ่อมก่อนขาย", "รองเท้าวินเทจพื้นโฟมเก่าอย่าซื้อแพงถ้ายังไม่ได้ลองกด"]'::jsonb,'','general','[]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('tool-milwaukee','tools.power','brand','Milwaukee','Milwaukee M12/M18: แบตปลอม','',ARRAY['milwaukee','m18','m12','redlithium']::text[],'["ของแท้น้ำหนักแน่น ของปลอมเบากว่าชัดเจน", "ไฟบอกระดับแบตติดไล่ทีละดวงและสว่าง", "ฉลากคม โลโก้ตรงกลาง สีแดง-ดำสม่ำเสมอ", "มี serial พิมพ์ตรงชัดเจน", "ขั้วต่อเรียบ เนียน งานกลึงดี"]'::jsonb,'["ไฟบอกระดับติดพร้อมกันทุกดวงหรือหรี่", "ไม่มี serial หรือพิมพ์เบี้ยว", "ตะเข็บบอดี้หยาบ พลาสติกบาง", "แพ็กเกจกระดาษแข็งแทนแพ็กพลาสติกใส"]'::jsonb,'','sourced','["https://www.techwalls.com/fake-vs-genuine-milwaukee-m18-battery-differences", "https://www.garagejournal.com/forum/threads/the-fake-milwaukee-m18-battery-thread.528520/"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('tool-dewalt','tools.power','brand','DeWalt','DeWalt 20V/18V: แบตปลอม','',ARRAY['dewalt','20v','flexvolt','xr']::text[],'["ใส่กับเครื่องแท้แล้วล็อกแน่นพอดี", "น็อตยึดบอดี้เป็นสีเงินหัวโดม (ตามที่ DeWalt ระบุ)", "ฟอนต์และสติกเกอร์ตรงกับของแท้ ไม่มีคำสะกดผิด", "มี serial/date code ให้สอบถาม DeWalt ได้"]'::jsonb,'["ใส่หลวมหรือฝืด", "น็อตสีดำหรือหัวแบน", "สะกดผิดบนฉลาก", "ใช้งานได้สั้นผิดปกติ"]'::jsonb,'','sourced','["https://www.slashgear.com/1923409/how-tell-dewalt-batteries-real-fake-knock-off-warning-signs-guide"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('tool-makita','tools.power','brand','Makita','Makita LXT 18V: แบตและตัวเครื่อง','',ARRAY['makita','lxt','bl1860','bl1850','มากีต้า']::text[],'["แบตแท้: ใต้แบตมีปลั๊กสีขาวใกล้ด้านหน้า กดปุ่มปลดเห็นแถบแดงด้านใน", "แบตแท้มีไฟบอกระดับ 4 ดวง (รุ่นมีดาว = มีชิปสื่อสารกับแท่นชาร์จ)", "เพลทใต้เครื่องมีรุ่น + serial ชัด", "เครื่องรุ่นมอเตอร์ไร้แปรงถ่านมีคำว่า Brushless/BL"]'::jsonb,'["แบต \"6.0Ah\" ราคาถูกมากแต่เบา = ใส่เซลล์น้อย", "เพลทถูกขูด"]'::jsonb,'ในไทยขายง่ายที่สุดในหมวดเครื่องมือ; เครื่องเปล่า (ไม่มีแบต) ราคาต่ำกว่าชุดพร้อมแบตมาก','general','[]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('tool-bosch-hikoki','tools.power','brand','','Bosch (เขียว vs น้ำเงิน) / HiKOKI (Hitachi)','',ARRAY['bosch','hikoki','hitachi','gsr','gbh']::text[],'["Bosch สีน้ำเงิน = รุ่นช่างมืออาชีพ, สีเขียว = รุ่นใช้ในบ้าน ราคาต่างกันมาก", "HiKOKI คือชื่อใหม่ของ Hitachi Power Tools (เปลี่ยนชื่อปี 2018)", "รุ่นเก่าที่เขียน Hitachi ยังหาอะไหล่ได้"]'::jsonb,'["ขายรุ่นสีเขียวในราคารุ่นสีน้ำเงิน"]'::jsonb,'','general','[]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('tool-test','tools.power','rule','','ทดสอบเครื่องมือไฟฟ้ามือสองก่อนซื้อ','',ARRAY['สว่าน','drill','grinder','หินเจียร','เครื่องมือ']::text[],'["ขอเสียบปลั๊ก/ใส่แบตลองเดินเครื่องทุกสปีด", "ฟังเสียงลูกปืน: หอนหรือแตก = ต้องเปลี่ยน", "ดูช่องระบายลม: ประกายไฟมากผิดปกติ = แปรงถ่าน/ทุ่นเสีย", "หัวจับดอก (chuck) หมุนตรงไม่ส่าย", "ดมกลิ่นไหม้ (ขดลวดเคยร้อนจัด)", "แบต: ถามรอบชาร์จ ดูว่าบวมไหม"]'::jsonb,'["ไม่ให้ลองเครื่อง", "บอดี้ร้าวใกล้ด้ามจับ", "แบตบวม = อันตราย ห้ามซื้อ"]'::jsonb,'','general','[]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('lux-lv-datecode','luxury','brand','Louis Vuitton','Louis Vuitton: date code และไมโครชิป','',ARRAY['louis vuitton','lv','monogram','damier','neverfull','speedy','date code']::text[],'["ยุค 80 ต้น: ตัวเลข 3–4 หลัก (ปี+เดือน)", "ราว 1990–2006: อักษร 2 ตัว (โรงงาน/ประเทศ) + ตัวเลข 4 หลัก หลักที่ 1,3 = เดือน หลักที่ 2,4 = ปี", "ราว 2007–ต้นปี 2021: อักษร 2 ตัว + ตัวเลข 4 หลัก หลักที่ 1,3 = สัปดาห์ หลักที่ 2,4 = ปี", "ตั้งแต่ราวมีนาคม 2021 เลิก date code ใช้ไมโครชิป NFC ฝังในตัวกระเป๋า (สแกนเองไม่ได้)", "date code ไม่ใช่ serial: กระเป๋าหลายใบมีรหัสเดียวกันได้"]'::jsonb,'["รหัสบอกปีที่รุ่นนั้นยังไม่ผลิต", "เลขสัปดาห์เกิน 53 หรือเดือนเกิน 12", "กระเป๋าผลิตหลัง 2021 แต่มี date code", "ลายโมโนแกรมถูกตัดกลับหัวด้านหลัง (Speedy/Keepall บางรุ่นเป็นปกติ ต้องเช็คตามรุ่น)"]'::jsonb,'ซื้อแบรนด์เนมมือสองให้ใช้บริการตรวจแท้ก่อนขายเสมอ','sourced','["https://lollipuff.com/louis-vuitton-date-code-guide", "https://collectorscage.com/blogs/authentication/louis-vuitton-date-code-vs-microchip-the-complete-buyers-guide-to-auth"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('lux-coach','luxury','brand','Coach','Coach: แผ่นหนัง creed และเลข serial','',ARRAY['coach','creed','signature c']::text[],'["ยุค 70–80: ตัวเลขล้วน", "ราว 1994–ต้นยุค 2000: อักษร(เดือน)+ตัวเลข(ปี)+อักษร(โรงงาน)-เลขรุ่น 4 หลัก เช่น K8P-9870 = ต.ค. 1998", "ราว 2014–2016: แผ่น creed ว่าง เลขรุ่นย้ายไปป้ายผ้าขาวเล็กๆ ด้านใน", "หลัง 2014: อักษร 1 ตัว + 4 หลัก - 5 หลัก; ขึ้นต้น F = รุ่น Outlet", "ลาย C ต้องต่อกันตรงตะเข็บ (ใบเต็ม)"]'::jsonb,'["รหัสบอกปีไม่ตรงกับทรงกระเป๋า", "หนังบาง อะไหล่เบา", "โลโก้เบี้ยว เย็บไม่เท่ากัน"]'::jsonb,'Coach วินเทจ (หนังวัวล้วน ยุค 80–90 ผลิตอเมริกา) มีตลาดสะสม ราคาสูงกว่า Coach Outlet','sourced','["https://blog.shopgoodwill.com/english/coach-purse-serial-number-guide"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('lux-general','luxury','rule','','แบรนด์เนม: กฎซื้อขายมือสองในไทย','',ARRAY['แบรนด์เนม','chanel','gucci','prada','hermes','ysl','dior']::text[],'["ห้ามตัดสินว่าแท้จากรูปอย่างเดียว ส่งตรวจกับบริการตรวจแท้ก่อนขาย", "ขอใบเสร็จ/การ์ด/ถุงผ้าเดิม แต่ของพวกนี้ก็ปลอมได้", "Chanel รุ่นเก่ามีสติกเกอร์ hologram + การ์ด serial ตรงกัน; ตั้งแต่ราวปลาย 2021 เปลี่ยนเป็นแผ่นโลหะ (microchip) ไม่มีการ์ด"]'::jsonb,'["ราคาถูกกว่าตลาดมาก", "ผู้ขายไม่ยอมให้ส่งตรวจ", "การ์ด/ใบเสร็จดูใหม่เกินอายุกระเป๋า"]'::jsonb,'','general','[]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('watch-gshock','luxury','brand','Casio','Casio G-Shock: ของแท้ vs ของปลอม','',ARRAY['g-shock','gshock','casio','ga-2100','dw-5600','casioak','จีช็อค']::text[],'["ฝาหลังเลขรุ่นตรงกับตัวเรือน ตัวอักษรสลักลึกคม มี \"20 BAR\"/\"WATER RESIST 200M\"", "เลขโมดูล (ตัวเลขในกรอบบนฝาหลัง) ต้องตรงกับรุ่น ค้นเทียบกับเว็บ Casio ได้", "ไฟส่องสว่างทั่วหน้าปัด ตัวเลขคม", "ปุ่มกดแน่นมีคลิก", "ขอบ bezel แนบสนิท สายยางนิ่มไม่แข็ง"]'::jsonb,'["เบากว่าสเปก", "ไฟหรี่/ไม่ทั่ว", "ปุ่มนิ่มหลวม", "ขอบมีช่องว่าง กระจกเป็นคลื่น"]'::jsonb,'G-Shock ปลอมเยอะมากในตลาดนัดไทย ราคาต่ำกว่าครึ่งของป้ายมักเป็นของปลอม; รุ่นลิมิเต็ด/คอลแลบมีตลาดสะสม','sourced','["https://www.gshockmod.com/how-to-spot-fake-g-shock-ultimate-authentication-guide-for-all-models"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('watch-seiko','luxury','brand','Seiko','Seiko วินเทจ: อ่านฝาหลังและเช็คหน้าปัดเปลี่ยน','',ARRAY['seiko','seiko 5','skx','presage','king seiko','grand seiko','ไซโก้']::text[],'["ฝาหลังมีรหัสกลไก-ตัวเรือน เช่น 6309-7040 (4 หลักแรก = กลไก)", "serial หลักแรก = ปี (หลักสุดท้ายของปี) หลักที่ 2 = เดือน (1–9, X/Y/Z หรือ O/N/D = ต.ค.–ธ.ค.)", "รหัสบนหน้าปัดใต้หลัก 6 ควรตรงกับรหัสกลไกบนฝาหลัง", "หน้าปัดยุคเดียวกับกลไก"]'::jsonb,'["\"franken\": ประกอบจากหลายเรือน หน้าปัดพิมพ์ใหม่/ทาสีใหม่ รหัสไม่ตรงกัน", "ตัวอักษรหน้าปัดหนา เบลอ โลโก้ตำแหน่งผิด", "Seiko 5 หน้าปัดสีแปลกที่ไม่มีในแคตตาล็อก"]'::jsonb,'Seiko วินเทจเดิมทั้งเรือนมีราคากว่าเรือนที่เปลี่ยนชิ้นส่วนมาก','sourced','["https://www.plus9time.com/seiko-case-back-information?rq=Serial", "https://www.namokimods.com/blogs/namokitimes/how-to-spot-a-feiko-pay-attention-to-these-9-things"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('watch-rolex','luxury','brand','Rolex','Rolex: จุดเช็คเบื้องต้น','',ARRAY['rolex','submariner','datejust','gmt','โรเล็กซ์']::text[],'["เลนส์ขยายวันที่ (cyclops) ขยาย 2.5 เท่า วันที่เต็มกรอบ", "รุ่นใหม่มีคำ ROLEX สลักวนขอบใน (rehaut) คมชัด", "ฝาหลังรุ่นทั่วไปเรียบ ไม่มีลาย/ไม่ใส", "เข็มวินาทีกวาดลื่น (กลไกอัตโนมัติ) ไม่กระตุกทีละวินาที", "สเตนเลสหนักประมาณ 100–160 กรัม", "รุ่นหลังปี 2002 มีมงกุฎเล็กสลักบนกระจกที่หลัก 6 (มองยาก)"]'::jsonb,'["เข็มวินาทีเดินทีละขีด (เว้นรุ่น Oysterquartz)", "ฝาหลังใสหรือมีลวดลาย", "เบา", "วันที่ขยายน้อย"]'::jsonb,'Rolex ต้องส่งร้านหรือผู้เชี่ยวชาญเปิดดูกลไกก่อนซื้อขายเสมอ ของปลอมเกรดสูงหลอกตาได้','sourced','["https://www.the1916company.com/blog/spotting-fake-rolex-watches.html"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('phone-iphone','phone','rule','Apple','iPhone มือสอง: เช็คก่อนซื้อ','',ARRAY['iphone','apple','ไอโฟน','icloud']::text[],'["ต้องไม่ติด Activation Lock / iCloud: ถ้าขึ้น \"iPhone Locked to Owner\" อย่าซื้อ", "ตั้งค่า > ทั่วไป > เกี่ยวกับ > ประวัติชิ้นส่วนและการซ่อม: \"ชิ้นส่วน Apple ของแท้\" = แท้, \"ไม่ทราบ\" = เปลี่ยนชิ้นส่วนไม่แท้/มือสอง", "ตั้งค่า > แบตเตอรี่ > สภาพแบตเตอรี่: ดูความจุสูงสุด (ต่ำกว่า 80% ควรเปลี่ยน)", "เกี่ยวกับ > การล็อกผู้ให้บริการ: \"ไม่มีข้อจำกัดซิม\" = ใช้ได้ทุกเครือข่าย", "ทดสอบปุ่ม ลำโพง ไมค์ (อัดเสียง) กล้องทุกตัว Face ID/Touch ID"]'::jsonb,'["ผู้ขายไม่ยอมลบเครื่อง/ออกจาก iCloud ต่อหน้า", "จอ \"ไม่ทราบ\" = เปลี่ยนจอเทียม สีเพี้ยน", "เครื่องติดล็อก MDM ของบริษัท", "ราคาถูกผิดปกติ = เครื่องหาย/ติดล็อก"]'::jsonb,'','sourced','["https://support.apple.com/en-gb/104999"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('phone-android','phone','rule','','Android มือสอง: เช็คก่อนซื้อ','',ARRAY['samsung','android','oppo','vivo','xiaomi','google pixel']::text[],'["ต้องออกจากบัญชี Google แล้ว (ไม่งั้นติด FRP lock หลังรีเซ็ต)", "กด *#06# ดู IMEI ให้ตรงกับกล่อง/ถาดซิม", "Samsung: เช็ค Knox/ล็อกบริษัท", "เปิดจอสีขาวล้วนดูจุดไหม้ (burn-in) ของจอ OLED"]'::jsonb,'["IMEI ไม่ตรงกล่อง", "ติดบัญชีเจ้าของเดิม", "จอมีเงาภาพค้าง"]'::jsonb,'','general','[]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('cam-film-check','generic','rule','','กล้องฟิล์มมือสอง: เช็คก่อนซื้อ','',ARRAY['กล้องฟิล์ม','film camera','กล้อง','canon ae-1','nikon fm2','pentax','olympus']::text[],'["ขึ้นชัตเตอร์แล้วกดหลายครั้ง ม่านต้องเปิด-ปิดสุด ไม่ค้าง", "ลองทุกสปีด เสียงต้องต่างกันชัด; โหมด B ปล่อยปุ่มแล้วปิดทันที", "เปิดฝาหลังดูซีลยาง/โฟมกันแสง: เป็นผงดำเหนียว = ต้องเปลี่ยนซีล (ราคาไม่แพง แต่ต้องบอกในประกาศ)", "ช่องถ่าน: คราบเขียว/ฟ้า = ถ่านรั่ว อาจวงจรเสีย", "วัดแสงต้องเปลี่ยนค่าเมื่อหันไปที่มืด/สว่าง", "บุบที่หัว pentaprism = เคยตก"]'::jsonb,'["กลิ่นอับชื้น/สนิมตามขอบฝา = เก็บในที่ชื้น", "ม่านชัตเตอร์ยับ/ใบมีดมีน้ำมัน"]'::jsonb,'','sourced','["https://petapixel.com/tips-buying-used-film-camera-lens/", "https://www.lomography.com/school/fa-ame1kpeg"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('cam-lens','generic','rule','','เลนส์มือสอง: รา ฝ้า ฝุ่น','',ARRAY['เลนส์','lens','รา','ฝ้า','fungus','haze']::text[],'["ส่องไฟฉายผ่านเลนส์จากด้านหลัง ดูทั้งหน้าและหลัง", "รา = เส้นใยคล้ายใยแมงมุม มักเริ่มที่ขอบ", "ฝ้า = ภาพมัวขาวทั่วชิ้นเลนส์", "ฝุ่นเล็กน้อยไม่กระทบภาพ ไม่ต้องลดราคามาก", "ม่านรูรับแสงต้องแห้ง ไม่มีน้ำมัน หุบ-กางไว", "แหวนโฟกัสหมุนลื่น ไม่ฝืดไม่ครูด"]'::jsonb,'["ราเยอะ/ฝ้าหนา ทำความสะอาดแพงหรือไม่หาย", "รอยขีดลึกที่เลนส์หน้า"]'::jsonb,'','sourced','["https://petapixel.com/tips-buying-used-film-camera-lens/"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('cam-pointshoot','generic','trend','','กล้องฟิล์มคอมแพกต์: ราคาพุ่ง','',ARRAY['point and shoot','คอมแพกต์','mju','contax t2','ricoh gr1','olympus mju','klasse','big mini']::text[],'["กล้องคอมแพกต์เลนส์ดี (Contax T2/T3, Ricoh GR1, Olympus mju-II, Fuji Klasse, Konica Big Mini) ราคาสูงขึ้นมากจากกระแสฟิล์ม", "กล้องคอมแพกต์ระบบอิเล็กทรอนิกส์ซ่อมยาก อะไหล่หายาก เช็คให้ใช้งานได้จริงก่อนซื้อ", "ลองใส่ถ่าน กดเปิด ดูเลนส์ยืดออก แฟลชทำงาน จอ LCD ไม่ซีด"]'::jsonb,'["จอ LCD ตัวเลขขาด", "เลนส์ยืดออกไม่สุด/มีเสียงขูด", "ขาย \"ไม่ได้เทส\" ราคาเต็ม"]'::jsonb,'ตลาดนัด/กระสอบญี่ปุ่นในไทยยังเจอกล้องคอมแพกต์ราคาถูก ขายต่อในกลุ่มกล้องฟิล์ม Facebook ได้ราคาดี','sourced','["https://www.photographytalk.com/why-are-point-and-shoot-film-cameras-so-expensive-now/"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('vinyl-grade','generic','rule','','แผ่นเสียง: เกรดสภาพ (Goldmine)','',ARRAY['แผ่นเสียง','vinyl','record','lp','goldmine']::text[],'["M (Mint) = ใหม่ไม่เคยเล่น, NM = เกือบใหม่, VG+ = มีรอยบางๆ ไม่มีเสียงรบกวน, VG = มีเสียงแตกเบาๆ, G = เสียงรบกวนชัด", "เกรดแผ่นและปกแยกกัน", "ส่องไฟดูรอยขีด ลองฟังถ้าทำได้", "ดูแผ่นบิด (warp) วางบนโต๊ะแล้วดูขอบ", "ข้อความในวงใกล้ป้ายกลาง (matrix/runout) ใช้ระบุว่าเป็นแผ่นพิมพ์ครั้งแรกหรือไม่"]'::jsonb,'["แผ่นบิดมาก", "รอยขีดลึกถึงเล็บสะดุด", "ปกขึ้นราหรือน้ำท่วม"]'::jsonb,'แผ่นพิมพ์ครั้งแรก (first press) และแผ่นไทยเก่า (ลูกทุ่ง/สตริงยุค 70–80) มีตลาดสะสม','sourced','["https://www.mylegendvinyl.co.uk/blogs/news/record-grading"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('cards-pokemon','generic','rule','','การ์ดโปเกมอน: ของแท้ vs ของปลอม','',ARRAY['pokemon','โปเกมอน','การ์ด','tcg','pokémon card']::text[],'["ส่องไฟฉายผ่านการ์ด: ของแท้มีชั้นสีดำกลางเนื้อการ์ด แสงผ่านน้อย", "ด้านหลังสีน้ำเงินเข้มไล่เฉด ไม่ซีด ไม่ม่วงจัด", "ฟอนต์และสัญลักษณ์ธาตุถูกต้อง ไม่สะกดผิด", "ผิวการ์ดด้านเรียบ ไม่มันวาวแบบพลาสติก", "เทียบความหนา/น้ำหนักกับการ์ดแท้"]'::jsonb,'["สะกดผิด/ค่า HP แปลก", "การ์ดฟอยล์ทั้งใบในชุดที่ไม่มี", "ขายเป็นกองราคาถูกมาก"]'::jsonb,'การ์ดเกรด (PSA/BGS) ราคาสูงกว่าการ์ดดิบมาก; ภาษาญี่ปุ่น/อังกฤษราคาต่างกัน','sourced','["https://blog.shopgoodwill.com/english/how-to-tell-if-a-pokemon-card-is-fake"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('toys-gunpla','generic','genre','','ของเล่น/ฟิกเกอร์/กันพลา','',ARRAY['gundam','กันพลา','figure','ฟิกเกอร์','bandai','tamiya','lego','hot wheels']::text[],'["ของในกล่องไม่แกะ (MISB) ราคาสูงกว่าแกะแล้วมาก", "Bandai แท้มีสติกเกอร์โฮโลแกรม/ตราบนกล่อง", "ฟิกเกอร์ญี่ปุ่นแท้มีสติกเกอร์ตัวแทนจำหน่าย ข้อความญี่ปุ่นบนกล่องพิมพ์คม", "เลโก้: ดูโลโก้ LEGO บนปุ่มตัวต่อทุกปุ่ม"]'::jsonb,'["ฟิกเกอร์ราคาถูกมาก สีเลอะ ข้อต่อหลวม = ของ bootleg", "กล่องพิมพ์สีซีด ฟอนต์เพี้ยน"]'::jsonb,'','general','[]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('game-retro','generic','genre','','เกมและเครื่องเล่นเกมเก่า','',ARRAY['famicom','nintendo','game boy','playstation','ps1','ps2','ตลับเกม','sega']::text[],'["ตลับ Nintendo แท้: ป้ายมีรหัส เช่น DMG-, น็อตหัวพิเศษ (gamebit), แผงวงจรมีโลโก้ Nintendo", "ลองเสียบเล่นจริงก่อนซื้อ", "ตลับ Game Boy Color/Advance เกมที่เซฟได้ใช้ถ่านกระดุม อาจหมด"]'::jsonb,'["ตลับเบาผิดปกติ ป้ายพิมพ์มัน/สีเพี้ยน (ของก๊อป)", "Pokémon ตลับ GBA ปลอมเยอะมาก"]'::jsonb,'','general','[]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('thai-sell-fees','generic','market','','ค่าธรรมเนียมขายออนไลน์ในไทย (คำนวณกำไร)','',ARRAY['shopee','lazada','tiktok shop','ค่าธรรมเนียม','ขาย']::text[],'["ทุกแพลตฟอร์มหักค่าคอมมิชชันตามหมวด + ค่าธุรกรรม/ชำระเงิน รวมราว 8–15% ของราคาขายสำหรับร้านทั่วไป (เช็คตัวเลขล่าสุดก่อนตั้งราคา)", "Facebook Marketplace/กลุ่ม ไม่มีค่าธรรมเนียม แต่ต้องจัดการโอน/ส่งเอง", "คิดค่าส่ง ค่ากล่อง และเวลาที่ใช้ด้วย"]'::jsonb,'["ตั้งราคาโดยไม่หักค่าธรรมเนียม ทำให้กำไรจริงหายไป"]'::jsonb,'','general','["https://flowaccount.com/blog/commission-fees-ecommerce-shopee-lazada-tiktok/"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('thai-markets','generic','market','','แหล่งซื้อของมือสองในไทย','',ARRAY['ตลาดนัด','คลองถม','จตุจักร','ตลาดรถไฟ','กระสอบ','โรงเกลือ']::text[],'["ตลาดโรงเกลือ (สระแก้ว) = แหล่งเสื้อผ้ากระสอบใหญ่ เช้ามืดของดีหมดก่อน", "คลองถม/วงเวียน 22 = เครื่องมือ อิเล็กทรอนิกส์ ของจิปาถะ", "ร้านมือสองญี่ปุ่น (ของจากกระสอบญี่ปุ่น) = กล้อง ของเล่น เครื่องครัว เสื้อผ้าแบรนด์ญี่ปุ่น", "ไปเช้า พกเงินสดย่อย ไฟฉาย และตลับเมตร"]'::jsonb,'["ซื้อตามอารมณ์โดยไม่สแกนเช็คราคาก่อน", "ต่อรองหลังรู้ว่ามีตำหนิ ไม่ใช่ก่อน"]'::jsonb,'','general','[]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('brand-patagonia','apparel.vintage','brand','Patagonia','Patagonia วินเทจ','',ARRAY['patagonia','synchilla','retro-x','snap-t','baggies']::text[],'["ตั้งแต่ปี 1988 ป้ายในมีรหัสรุ่น + รหัสฤดู/ปี เช่น S9 (ต้องดูแบบป้ายประกอบว่า 1989 หรือ 1999)", "ตั้งแต่ปี 1995 มีรหัสสี 3–4 ตัวอักษรบนป้าย", "ทุกตัวมี RN51884", "ก่อน 1986 ระบุปีจากรหัสไม่ได้ ดูแบบป้ายคอแทน"]'::jsonb,'["รหัสรุ่นค้นแล้วไม่ตรงกับตัวเสื้อ", "คุณภาพงานเย็บหยาบ ลาย/โลโก้เพี้ยน"]'::jsonb,'Snap-T, Retro-X, Synchilla ยุค 80–90 ผลิตอเมริกา ราคาดีในกลุ่มเอาท์ดอร์วินเทจ','sourced','["https://trussarchive.com/guides/how-to-identify-patagonia"]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
insert into public.knowledge (id,category,kind,brand,title,era,keywords,cues,red_flags,value_notes,confidence,sources) values ('brand-tnf','apparel.vintage','brand','The North Face','The North Face วินเทจ','',ARRAY['north face','tnf','nuptse','mountain jacket','gore-tex']::text[],'["ป้ายยุค 70–80: ป้ายน้ำตาล/ครีมลายเส้นขอบ", "ยุค 90: ป้ายดำโลโก้ขาว ตามด้วยป้ายรุ่น Summit Series/Steep Tech", "Nuptse 1996 ดั้งเดิม ราคาสูงสุดในกลุ่มขนเป็ด", "รุ่นมี Gore-Tex มีป้าย Gore-Tex แยก"]'::jsonb,'["TNF ปลอมเยอะมาก: ปักโลโก้หนา ซิปไม่มียี่ห้อ YKK", "ขนเป็ดยุบเป็นก้อน/มีกลิ่น"]'::jsonb,'','general','[]'::jsonb) on conflict (id) do update set category=excluded.category,kind=excluded.kind,brand=excluded.brand,title=excluded.title,era=excluded.era,keywords=excluded.keywords,cues=excluded.cues,red_flags=excluded.red_flags,value_notes=excluded.value_notes,confidence=excluded.confidence,sources=excluded.sources,updated_at=now();
